70	export function highlightMentions(body: string): string {
71	  return body.replace(
72	    MENTION_PATTERN,
73	    (_match, prefix: string, handle: string) =>
74	      `${prefix}<span class="mention">@${handle}</span>`,
75	  );
76	}
