1	/**
2	 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
3	 *
4	 * Must call (do not reimplement): archivePatch, shouldFilterArchived
5	 */
6	import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
7	import { newId } from "@/lib/id";
8	import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
9	import { comments, getDb, users } from "@/server/db";
10	import { toIsoTimestamp } from "@/types/common";
11	import { orgPredicate } from "./base-repository";
12	import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
13	import { toComment, toUser } from "./_mappers";
14	import type {
15	  CreateCommentInput,
16	  ListCommentsInput,
17	  UpdateCommentInput,
18	} from "@/schemas/comment";
19	import type {
20	  Comment,
21	  CommentThreadNode,
22	  CommentWithAuthor,
23	} from "@/types/comment";
24	import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";
25	
26	export async function findCommentById(
27	  orgId: OrgId,
28	  commentId: CommentId,
29	): Promise<Comment | null> {
30	  const row = getDb()
31	    .select()
32	    .from(comments)
33	    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
34	    .get();
35	  return row ? toComment(row) : null;
36	}
37	
38	export async function listComments(
39	  input: ListCommentsInput,
40	): Promise<Page<CommentWithAuthor>> {
41	  const db = getDb();
42	  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };
43	
44	  const filters = compact(
45	    orgPredicate(comments.orgId, input.orgId),
46	    eq(comments.issueId, input.issueId),
47	    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
48	  );
49	
50	  const total = db
51	    .select({ value: count() })
52	    .from(comments)
53	    .where(and(...filters))
54	    .get();
55	
56	  const rows = db
57	    .select({ comment: comments, author: users })
58	    .from(comments)
59	    .innerJoin(users, eq(users.id, comments.authorId))
60	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
61	    .orderBy(desc(comments.createdAt), desc(comments.id))
62	    .limit(probeLimit(input.limit))
63	    .all();
64	
65	  return toPage(
66	    rows,
67	    input.limit,
68	    total?.value ?? 0,
69	    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
70	    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
71	  );
72	}
73	
74	/**
75	 * The whole thread for one issue, in reading order: top-level comments oldest
76	 * first, each followed by its replies. A deleted top-level comment takes its
77	 * thread with it — nothing to anchor the replies to once the opener is gone.
78	 */
79	export async function listThread(
80	  orgId: OrgId,
81	  issueId: IssueId,
82	): Promise<readonly CommentThreadNode[]> {
83	  const rows = getDb()
84	    .select({ comment: comments, author: users })
85	    .from(comments)
86	    .innerJoin(users, eq(users.id, comments.authorId))
87	    .where(
88	      and(
89	        orgPredicate(comments.orgId, orgId),
90	        eq(comments.issueId, issueId),
91	      ),
92	    )
93	    .orderBy(asc(comments.createdAt))
94	    .all();
95	
96	  const decorated: CommentWithAuthor[] = rows.map((row) => ({
97	    ...toComment(row.comment),
98	    author: toUser(row.author),
99	  }));
100	
101	  const repliesBy = new Map<string, CommentWithAuthor[]>();
102	  for (const comment of decorated) {
103	    if (comment.parentId === null) continue;
104	    const bucket = repliesBy.get(comment.parentId) ?? [];
105	    bucket.push(comment);
106	    repliesBy.set(comment.parentId, bucket);
107	  }
108	
109	  return decorated
110	    .filter((comment) => comment.parentId === null && comment.archivedAt === null)
111	    .map((comment) => ({
112	      comment,
113	      replies: repliesBy.get(comment.id) ?? [],
114	    }));
115	}
116	
117	export async function countComments(
118	  orgId: OrgId,
119	  issueId: IssueId,
120	): Promise<number> {
121	  const row = getDb()
122	    .select({ value: count() })
123	    .from(comments)
124	    .where(
125	      and(
126	        orgPredicate(comments.orgId, orgId),
127	        eq(comments.issueId, issueId),
128	        isNull(comments.archivedAt),
129	      ),
130	    )
131	    .get();
132	  return row?.value ?? 0;
133	}
134	
135	export async function insertComment(
136	  input: CreateCommentInput,
137	  authorId: UserId,
138	): Promise<Comment> {
139	  const stamp = toIsoTimestamp(new Date());
140	  const row = getDb()
141	    .insert(comments)
142	    .values({
143	      id: newId(),
144	      orgId: input.orgId,
145	      issueId: input.issueId,
146	      authorId,
147	      body: input.body,
148	      parentId: input.parentId,
149	      editedAt: null,
150	      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
151	      createdAt: stamp,
152	      updatedAt: stamp,
153	    })
154	    .returning()
155	    .get();
156	
157	  return toComment(row);
158	}
159	
160	/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
161	export async function updateComment(
162	  input: UpdateCommentInput,
163	): Promise<Comment> {
164	  const stamp = toIsoTimestamp(new Date());
165	  const row = getDb()
166	    .update(comments)
167	    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
168	    .where(
169	      and(
170	        orgPredicate(comments.orgId, input.orgId),
171	        eq(comments.id, input.commentId),
172	      ),
173	    )
174	    .returning()
175	    .get();
