    }));
}

/**
 * Every comment below `rootId` at any depth, in the order they appear in
 * `ordered` (the posting order the thread was loaded in).
 */
function descendantsOf(
  rootId: string,
  childrenOf: ReadonlyMap<string, readonly CommentWithAuthor[]>,
  ordered: readonly CommentWithAuthor[],
): readonly CommentWithAuthor[] {
  const found = new Set<string>();
  const pending = [rootId];

  while (pending.length > 0) {
    const parentId = pending.pop() as string;
    for (const child of childrenOf.get(parentId) ?? []) {
